/* Types */
export type AboutInfo = {
	version: string,
	/**  Product name and version, such as "macOS 26.1.0". */
	os: string,
	arch: string,
};

/**
 *  Stable diagnostics classification. Native/parser text and filter content
 *  never cross the privileged IPC boundary.
 */
export type BlockerFailure = "site_preferences_unavailable" | "generation_exhausted" | "compiler_dispatch_rejected" | "compiler_unavailable" | "compile_source_unavailable" | "compile_invalid_source" | "compile_resource_limit" | "compile_internal" | "compiled_artifact_mismatch" | "native_dispatch_rejected" | "native_unsupported" | "native_unsupported_artifact" | "native_invalid_artifact" | "native_compilation" | "native_installation" | "native_cleanup" | "native_superseded" | "contradictory_native_settlement";

export type BlockerPhase = "unavailable" | "uninitialized" | "compiling" | "installing" | "ready" | "failed" | "retired";

/**  Host-initiated picker controls, available only to privileged main chrome. */
export type BlockerPickerAction = { kind: "start" } | { kind: "read"; session: string } | { kind: "preview"; session: string; enabled: boolean } | { kind: "stop"; session: string };

export type BlockerPickerView = {
	session: string,
	active: boolean,
	selection: BlockerSelectionView | null,
};

/**
 *  Authority of the focused profile's durable blocker preference.
 *  `Reconciling` and `Unavailable` are intentionally distinct from native
 *  policy state: the browser may still know which generation is installed
 *  while refusing to guess what durable preference should replace it.
 */
export type BlockerPreferenceState = "authoritative" | "updating" | "reconciling" | "unavailable";

/**
 *  Effective protection for the focused profile's exact native policy.
 *  This is derived in Rust from both desired and retained state. Privileged
 *  chrome must not infer protection from a pending preference and accidentally
 *  present a retained allow-all generation as active blocking.
 */
export type BlockerProtection = "disabled" | "pending" | "active" | "degraded" | "unavailable";

/**
 *  Exact coverage of the generation which native code proved applied.
 *  Counts are bounded far below JavaScript's exact-integer ceiling by the
 *  blocker compiler's hard rule limits.
 */
export type BlockerRuleCoverage = {
	source_rules: number,
	accepted_rules: number,
	rejected_rules: number,
	platform_omitted_rules: number,
	platform_approximated_rules: number,
	platform_resource_approximated_rules: number,
	platform_source_kind_approximated_rules: number,
	platform_attribution_approximated_rules: number,
	blocking_rule_entries: number,
};

/**
 *  Volatile, process-local health counters for the exact applied runtime
 *  matcher. Decimal strings preserve the full saturating `u64` range in
 *  JavaScript. These counters are never persisted and contain no request,
 *  origin, URL, profile, or rule identity.
 */
export type BlockerRuntimeDiagnostics = {
	total_decisions: string,
	candidate_budget_exhausted: string,
	matcher_unavailable: string,
	matcher_unprepared: string,
	attribution_unavailable: string,
	evaluation_errors: string,
};

export type BlockerSelectionView = {
	identity: string,
	label: string,
	count: number,
	positional: boolean,
};

export type BlockerSiteAction = { kind: "save_selection"; session: string; selection: string } | { kind: "retry" } | { kind: "pause"; paused: boolean } | { kind: "set_hide_enabled"; id: string; enabled: boolean } | { kind: "remove_hide"; id: string };

/**  Exact privileged site-control context; never accepted from ordinary page IPC. */
export type BlockerSiteContext = {
	profile: string,
	tab: string,
	site: string,
	revision: string,
};

export type BlockerSiteView = {
	context: BlockerSiteContext,
	paused: boolean,
	private_session: boolean,
	ready: boolean,
	busy: boolean,
	hides: PersonalHideView[],
};

/**
 *  Stable package-refresh failure category. Endpoint, parser, and native
 *  strings are intentionally never forwarded to privileged JavaScript.
 */
export type BlockerSourceFailure = "transport" | "metadata" | "clock" | "manifest" | "target" | "license" | "rollback" | "storage" | "catalog" | "internal";

/**
 *  Exact authenticated identities for source-package transition diagnostics.
 *  This is boxed in [`BlockerStatusView`] so infrequent debug strings do not
 *  inflate every application projection on the shell actor's hot path.
 */
export type BlockerSourceIdentities = {
	package_manifest_sha256: string | null,
	candidate_revision: string | null,
	candidate_manifest_sha256: string | null,
	installed_manifest_sha256: string | null,
};

/**  Sanitized state of the authenticated filter-package supply chain. */
export type BlockerSourcePhase = "not_configured" | "durable_activation_unsupported" | "storage_unavailable" | "clock_unsafe" | "idle" | "fresh" | "stale" | "refreshing" | "failed" | "shutdown";

/**  Authority which admitted the displayed filter package. */
export type BlockerSourceProvenance = "release_bundle" | "tuf_repository" | "official_https";

export type BlockerStatsView = {
	today: number | null,
	last7Days: number | null,
	days: (number | null)[],
};

export type BlockerStatusChanged = BlockerStatusView;

export type BlockerStatusView = {
	site: BlockerSiteView | null,
	projection_revision: string,
	protection: BlockerProtection,
	phase: BlockerPhase,
	preference: BlockerPreferenceState,
	config_revision: string | null,
	desired_enabled: boolean | null,
	applied_enabled: boolean | null,
	desired_generation: string | null,
	retained_generation: string | null,
	failure: BlockerFailure | null,
	retryable: boolean,
	retries_remaining: number,
	/**
	 *  Boxed with the other diagnostic-only payloads so ordinary projection
	 *  queue entries do not carry the full coverage report inline.
	 */
	applied_coverage: BlockerRuleCoverage | null,
	/**
	 *  Boxed because the six decimal counters are diagnostic-only and should
	 *  not inflate every projection enum value on the actor/UI hot path.
	 */
	runtime_diagnostics: BlockerRuntimeDiagnostics | null,
	source_phase: BlockerSourcePhase,
	source_failure: BlockerSourceFailure | null,
	source_package_revision: string | null,
	source_installed_revision: string | null,
	source_package_provenance: BlockerSourceProvenance | null,
	source_installed_provenance: BlockerSourceProvenance | null,
	source_identities: BlockerSourceIdentities | null,
	source_package_created_unix: string | null,
	source_package_expires_unix: string | null,
	source_package_stale: boolean | null,
	/**
	 *  Advisory source update cadence. This never downgrades a healthy
	 *  release-bundled policy.
	 */
	source_refresh_due: boolean,
	source_count: number | null,
	source_bytes: number | null,
	source_activation_pending: boolean,
	source_material_repair_pending: boolean,
	source_material_repair_retry_pending: boolean,
	source_repair_retry_pending: boolean,
	source_last_refresh_attempt_unix: string | null,
	source_refresh_operation: string | null,
	/**  Authoritative source-policy capability for the focused profile. */
	can_enable: boolean,
	/**  Authoritative refresh admission capability for the active supply mode. */
	can_refresh_sources: boolean,
};

export type BookmarkCall = 
/**
 *  A folder's contents and the folders above it; no `folder` is the top
 *  level.
 */
{ kind: "list"; folder: string | null } | 
/**  The listing of whichever folder holds `id`, so it can be shown in place. */
{ kind: "reveal"; id: string } | { kind: "search"; query: string } | { kind: "add_folder"; parent: string | null; title: string } | 
/**  A page added by hand; an empty `title` takes the page's site. */
{ kind: "add_link"; parent: string | null; title: string; url: string } | { kind: "rename"; id: string; title: string } | 
/**  Moves `id` into `parent` at `index` among its new siblings. */
{ kind: "move"; id: string; parent: string | null; index: number } | 
/**  Removes a bookmark, or a folder with everything in it. */
{ kind: "remove"; id: string };

export type BookmarkCrumb = {
	id: string,
	title: string,
};

export type BookmarkError = "missing" | 
/**  The profile holds the maximum, or the folder is nested too deep. */
"full" | 
/**  A folder cannot move into itself. */
"cycle" | "invalid" | "unavailable" | "capacity";

export type BookmarkResponse = { kind: "listing"; folder: string | null; 
/**  Folders from the top level down to `folder`, `folder` last. */
path: BookmarkCrumb[]; items: BookmarkView[] } | { kind: "results"; items: BookmarkView[] } | 
/**  A write applied; `id` names what an add created. */
{ kind: "saved"; id: string | null } | { kind: "error"; error: BookmarkError };

export type BookmarkView = {
	id: string,
	title: string,
	/**  Absent for a folder. */
	url: string | null,
	icon: IconRef | null,
	/**  Direct children, for a folder. */
	children: number,
	/**  The folder it lives in; absent at the top level. */
	parent: string | null,
};

